1	/**
2	 * Tests for T5: run-claude.ts — writeBlockedAndPush writes blocked_context.
3	 *
4	 * Unit tests — node:child_process is fully mocked to avoid real git and
5	 * real claude invocations.
6	 *
7	 * Covers:
8	 *   1. blocked_context written with wip_branch, wip_sha, pushed_at on crash-block
9	 *   2. wip_branch matches the taskBranch passed to runClaude
10	 *   3. wip_sha falls back to "unknown" when git rev-parse throws
11	 *   4. blocked_context stays null when task reaches in_review (happy path)
12	 */
13	
14	import { describe, it, expect, vi, afterEach } from "vitest";
15	import {
16	  mkdtempSync,
17	  mkdirSync,
18	  writeFileSync,
19	  readFileSync,
20	  rmSync,
21	} from "node:fs";
22	import { tmpdir } from "node:os";
23	import { join } from "node:path";
24	import { EventEmitter } from "node:events";
25	import { execSync, spawn } from "node:child_process";
26	import { stringify as yamlStringify, parse as parseYaml } from "yaml";
27	import type { Task } from "../src/types/task.js";
28	import { runClaude } from "../src/loop/run-claude.js";
29	
30	// ── Mock node:child_process ───────────────────────────────────────────────────
31	
32	vi.mock("node:child_process", async (importOriginal) => {
33	  const actual = await importOriginal<typeof import("node:child_process")>();
34	  return {
35	    ...actual,
36	    spawn: vi.fn(),
37	    execSync: vi.fn(),
38	  };
39	});
40	
41	// ── Fake child process factory ────────────────────────────────────────────────
42	
43	/**
44	 * Returns a fake ChildProcess-like object whose close event fires asynchronously.
45	 * `onSpawn` is called synchronously so the caller can mutate the task YAML
46	 * before the close event resolves runClaude's Promise.
47	 */
48	function makeFakeChild(opts: {
49	  exitCode?: number | null;
50	  onSpawn?: () => void;
51	} = {}): ReturnType<typeof spawn> {
52	  const { exitCode = 0, onSpawn } = opts;
53	  const stdoutEmitter = Object.assign(new EventEmitter(), {
54	    setEncoding: vi.fn(),
55	  });
56	  const stderrEmitter = Object.assign(new EventEmitter(), {
57	    setEncoding: vi.fn(),
58	  });
59	  const childEmitter = new EventEmitter();
60	
61	  const child = {
62	    stdout: stdoutEmitter,
63	    stderr: stderrEmitter,
64	    on: (event: string, handler: (...args: unknown[]) => void) => {
65	      childEmitter.on(event, handler);
66	      return child;
67	    },
68	  };
69	
70	  // Emit close on the next microtask tick so callers can register handlers first.
71	  Promise.resolve().then(() => {
72	    onSpawn?.();
73	    childEmitter.emit("close", exitCode, null);
74	  });
75	
76	  return child as unknown as ReturnType<typeof spawn>;
77	}
78	
79	// ── Constants ─────────────────────────────────────────────────────────────────
80	
81	const FEATURE_ID = "test-feature";
82	const TASK_ID = "T5";
83	const TASK_BRANCH = `feature/${FEATURE_ID}-${TASK_ID}`;
84	const GIT_AUTHOR_EMAIL = "test@example.com";
85	const FAKE_SHA = "abc123def456789deadbeef";
86	
87	// ── Temp workspace helpers ────────────────────────────────────────────────────
88	
89	const tmpDirs: string[] = [];
90	
91	afterEach(() => {
92	  while (tmpDirs.length) {
93	    const d = tmpDirs.pop()!;
94	    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
95	  }
96	  vi.clearAllMocks();
97	});
98	
99	function makeTempWorkspace(
100	  initialStatus: Task["status"] = "in_progress",
101	): { workspaceRoot: string; taskYamlPath: string } {
102	  const dir = mkdtempSync(join(tmpdir(), "run-claude-test-"));
103	  tmpDirs.push(dir);
104	  const tasksDir = join(dir, "docs", "features", FEATURE_ID, "tasks");
105	  mkdirSync(tasksDir, { recursive: true });
106	
107	  const task: Task = {
108	    id: TASK_ID,
109	    title: "Test task",
110	    repo: "test-repo",
111	    status: initialStatus,
112	    depends_on: [],
113	    blocked_reason: null,
114	    blocked_context: null,
115	    branch: TASK_BRANCH,
116	    execution: {
117	      actor_type: "agent",
118	      last_updated_by: GIT_AUTHOR_EMAIL,
119	      last_updated_at: "2026-04-15T10:00:00Z",
120	    },
121	    pr: { url: "", status: "not_created" },
122	    workspace_pr: null,
123	    log: [],
124	  };
125	
126	  const taskYamlPath = join(tasksDir, `${TASK_ID}.yaml`);
127	  writeFileSync(taskYamlPath, yamlStringify(task), "utf-8");
128	  return { workspaceRoot: dir, taskYamlPath };
129	}
130	
131	function readTask(workspaceRoot: string): Task {
132	  return parseYaml(
133	    readFileSync(
