140	// ── Tests ─────────────────────────────────────────────────────────────────────
141	
142	describe("runClaude — crash-block path (T5)", () => {
143	  it("writes blocked_context with wip_branch, wip_sha, pushed_at when task stays in_progress", async () => {
144	    const { workspaceRoot } = makeTempWorkspace("in_progress");
