148	
149	    // git rev-parse returns fake SHA; all other git commands are no-ops
150	    vi.mocked(execSync).mockImplementation((cmd: unknown) => {
151	      if (String(cmd).includes("rev-parse")) return `${FAKE_SHA}\n` as never;
152	      return "" as never;
153	    });
154	
