187	    vi.mocked(spawn).mockReturnValueOnce(makeFakeChild({ exitCode: 1 }));
188	    vi.mocked(execSync).mockImplementation((cmd: unknown) => {
189	      if (String(cmd).includes("rev-parse")) return `${FAKE_SHA}\n` as never;
