210	  });
211	
212	  it("falls back to wip_sha 'unknown' when git rev-parse throws", async () => {
213	    const { workspaceRoot } = makeTempWorkspace("in_progress");
214	
215	    vi.mocked(spawn).mockReturnValueOnce(makeFakeChild({ exitCode: 0 }));
216	    vi.mocked(execSync).mockImplementation((cmd: unknown) => {
217	      if (String(cmd).includes("rev-parse")) throw new Error("not a git repo");
218	      return "" as never;
219	    });
220	
221	    await runClaude({
222	      taskId: TASK_ID,
223	      featureId: FEATURE_ID,
224	      workspaceRoot,
225	      taskRepoRoot: workspaceRoot,
226	      workflowLocalPath: workspaceRoot,
227	      agentContext: "test",
228	      maxTurns: 10,
