235	
236	    const task = readTask(workspaceRoot);
237	    expect(task.blocked_context?.wip_sha).toBe("unknown");
238	    // other fields still written
239	    expect(task.blocked_context?.wip_branch).toBe(TASK_BRANCH);
240	    expect(task.blocked_context?.pushed_at).toBeTruthy();
241	  });
242	
243	  it("does NOT write blocked_context when task reaches in_review", async () => {
244	    const { workspaceRoot } = makeTempWorkspace("in_progress");
245	
246	    // stub claude updates the task to in_review before close fires
