260	
261	    const result = await runClaude({
262	      taskId: TASK_ID,
263	      featureId: FEATURE_ID,
264	      workspaceRoot,
265	      taskRepoRoot: workspaceRoot,
266	      workflowLocalPath: workspaceRoot,
267	      agentContext: "test",
