131	  ) as { management_repo: string; repos: RepoEntry[] };
132	  const mgmtId = yaml.management_repo;
133	  const mgmtRepo = yaml.repos.find((r) => r.id === mgmtId);
134	  if (!mgmtRepo) throw new Error(`Management repo "${mgmtId}" not found in workspace.yaml`);
135	  const { owner, repo } = parseGitHubCoords(mgmtRepo.github);
136	  return { owner, repo, baseBranch: mgmtRepo.base_branch ?? "main" };
137	}
