241	
242	    let outcome: CycleOutcome = "idle";
243	    const pulledWorkspaceRoots: string[] = [];
244	
245	    outerLoop:
246	    for (const watchUrl of config.watches) {
247	      if (haltedUrls.has(watchUrl)) continue;
248	
249	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
250	      pulledWorkspaceRoots.push(workspaceLocalPath);
