1	/**
2	 * Orchestrator side-effect: write terminal task status to the task YAML.
3	 *
4	 * Called after the executor returns a result. Translates ExecutorResult
5	 * terminal_status values into the workflow task status schema and commits
6	 * the change to the management repo's task branch.
7	 */
8	
9	import { readFileSync, writeFileSync } from "node:fs";
10	import { execSync, spawnSync } from "node:child_process";
11	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
12	import type { Task } from "../types/task.js";
13	import type { ExecutorResult } from "@workflow/runtime-abi";
14	import { taskYamlAbsPath, taskYamlRelPath } from "../paths.js";
15	import { buildGitCommitEnv } from "../git-env.js";
16	
17	export interface MutateTaskYamlOpts {
18	  workspaceRoot: string;
19	  featureId: string;
20	  taskId: string;
21	  taskBranch: string;
22	  result: ExecutorResult;
23	  /** Implementation repo PR URL — required when result.terminal_status === "in_review". */
24	  prUrl?: string;
25	  gitAuthorEmail: string;
26	  gitAuthorName?: string;
27	  sshKeyPath?: string;
28	}
29	
30	/**
31	 * Write the terminal task status implied by ExecutorResult to the task YAML
32	 * and commit+push to the task branch.
33	 *
34	 * Status transitions:
35	 *   in_review → task.status = "in_review", task.pr.url = prUrl, task.pr.status = "open"
36	 *   blocked   → task.status = "blocked", task.blocked_reason + task.blocked_suggestion
37	 *   failed    → task.status = "blocked", task.blocked_reason = "executor_failed:<reason>"
38	 *
39	 * Non-throwing: returns an error string on failure so the caller can decide
40	 * whether to surface or swallow the error.
41	 */
42	export function mutateTaskYaml(opts: MutateTaskYamlOpts): string | undefined {
43	  const {
44	    workspaceRoot,
45	    featureId,
46	    taskId,
47	    taskBranch,
48	    result,
49	    prUrl,
50	    gitAuthorEmail,
51	    gitAuthorName = gitAuthorEmail,
52	    sshKeyPath,
53	  } = opts;
54	
55	  const now = new Date().toISOString();
56	  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
57	  let task: Task;
58	  try {
59	    task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
60	  } catch (e) {
61	    return `failed to read task YAML: ${String(e)}`;
62	  }
63	
64	  task.execution.last_updated_by = gitAuthorEmail;
65	  task.execution.last_updated_at = now;
66	
67	  switch (result.terminal_status) {
68	    case "in_review":
69	      task.status = "in_review";
70	      if (prUrl) {
71	        task.pr = { url: prUrl, status: "open" };
72	      }
73	      break;
74	
75	    case "blocked":
76	      task.status = "blocked";
77	      task.blocked_reason = result.blocked_reason ?? "unknown";
78	      if (result.blocked_suggestion) {
79	        task.blocked_suggestion = result.blocked_suggestion;
80	      }
81	      break;
82	
83	    case "failed":
84	      task.status = "blocked";
85	      task.blocked_reason = `executor_failed:${result.blocked_reason ?? "unknown"}`;
86	      if (result.blocked_suggestion) {
87	        task.blocked_suggestion = result.blocked_suggestion;
88	      }
89	      break;
90	  }
91	
92	  try {
93	    writeFileSync(yamlPath, yamlStringify(task), "utf-8");
94	  } catch (e) {
