42	function curlJson(args: string[]): unknown {
43	  const result = spawnSync("curl", args, {
44	    encoding: "utf-8",
45	    stdio: ["ignore", "pipe", "pipe"],
46	  });
47	  if (result.error) throw result.error;
48	  const stdout = result.stdout ?? "";
