1	/**
2	 * Orchestrator side-effect: apply the auto-ready rule.
3	 *
4	 * When a task is marked done, scan sibling tasks in the same feature and
5	 * transition any whose entire `depends_on` list is now satisfied from
6	 * `todo` → `ready`. Called by `handleMergedPrs` after writing task.status = "done".
7	 *
8	 * This module extracts the auto-ready logic from `poll/handle-merged-prs.ts`
9	 * into a standalone side-effect so it can be tested and invoked independently.
10	 */
11	
12	import { readFileSync, writeFileSync } from "node:fs";
13	import { join } from "node:path";
14	import { readdirSync } from "node:fs";
15	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
16	import type { Task } from "../types/task.js";
17	import { featuresRoot, taskYamlRelPath, TASKS_DIR } from "../paths.js";
18	
19	export interface UnblockDepsOpts {
20	  workspaceRoot: string;
21	  featureId: string;
22	  /** The task ID that was just marked done — used as the anchor for dep checks. */
23	  completedTaskId: string;
24	  gitAuthorEmail: string;
25	}
26	
27	export interface UnblockDepsResult {
28	  /** Relative paths of all YAML files mutated (for git add). */
29	  mutatedRelPaths: string[];
30	  /** IDs of tasks that were transitioned to ready. */
31	  readiedTaskIds: string[];
32	}
33	
34	/**
35	 * Scan sibling task YAMLs in the same feature directory. For each that is in
36	 * `todo` status and whose entire `depends_on` list is satisfied (all done),
37	 * write `status: ready` and append a ready log entry.
38	 *
39	 * Writes directly to disk — the caller is responsible for git add/commit.
40	 *
41	 * Non-throwing: individual sibling read/write errors are skipped silently to
42	 * avoid blocking the overall done-transition on one bad sibling file.
43	 */
44	export function applyAutoReadyRule(opts: UnblockDepsOpts): UnblockDepsResult {
45	  const { workspaceRoot, featureId, completedTaskId, gitAuthorEmail } = opts;
46	
47	  const tasksDir = join(featuresRoot(workspaceRoot), featureId, TASKS_DIR);
48	  const mutatedRelPaths: string[] = [];
49	  const readiedTaskIds: string[] = [];
50	
51	  let siblingFiles: string[] = [];
52	  try {
53	    siblingFiles = readdirSync(tasksDir).filter(
54	      (f) => /^T\d+\.yaml$/.test(f) && f !== `${completedTaskId}.yaml`,
55	    );
56	  } catch {
57	    return { mutatedRelPaths, readiedTaskIds };
58	  }
59	
60	  // Build a status map including the just-completed task.
61	  const taskStatusMap = new Map<string, string>([[completedTaskId, "done"]]);
62	  for (const sibFile of siblingFiles) {
63	    try {
64	      const sibTask = parseYaml(
65	        readFileSync(join(tasksDir, sibFile), "utf-8"),
66	      ) as Task;
67	      taskStatusMap.set(sibTask.id, sibTask.status);
68	    } catch { /* skip */ }
69	  }
70	
71	  for (const sibFile of siblingFiles) {
72	    try {
73	      const sibPath = join(tasksDir, sibFile);
74	      const sibTask = parseYaml(readFileSync(sibPath, "utf-8")) as Task;
75	
76	      if (sibTask.status !== "todo") continue;
77	      if (!Array.isArray(sibTask.depends_on) || !sibTask.depends_on.includes(completedTaskId)) continue;
78	
79	      const allDepsDone = sibTask.depends_on.every(
80	        (depId) => taskStatusMap.get(depId) === "done",
81	      );
82	      if (!allDepsDone) continue;
83	
84	      const now = new Date().toISOString();
85	      sibTask.status = "ready";
86	      sibTask.log.push({
87	        action: "ready",
88	        by: gitAuthorEmail,
89	        at: now,
90	        note: `Task activated — dependency ${completedTaskId} merged and marked done.`,
91	      });
92	
93	      writeFileSync(sibPath, yamlStringify(sibTask), "utf-8");
94	      mutatedRelPaths.push(taskYamlRelPath(featureId, sibTask.id));
95	      readiedTaskIds.push(sibTask.id);
96	    } catch { /* skip individual sibling errors */ }
97	  }
98	
99	  return { mutatedRelPaths, readiedTaskIds };
100	}
