75	      `Cannot parse GitHub owner/repo from URL: "${sshUrl}". ` +
76	        `Expected SSH format: git@github.com:<owner>/<repo>[.git]`,
77	    );
78	  }
79	  return { owner: match[1], repo: match[2] };
